import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.BqDA2HS7.js";const u=JSON.parse('{"title":"规划路由","description":"","frontmatter":{},"headers":[],"relativePath":"planning.md","filePath":"planning.md"}'),i={name:"planning.md"};function o(n,t,l,s,h,p){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="规划路由" tabindex="-1">规划路由 <a class="header-anchor" href="#规划路由" aria-label="Permalink to &quot;规划路由&quot;">​</a></h1><p>规划路由保留接入方 Agent 的原生执行循环。模型回复、工具调用与结果配对、实际来源和 已接受历史随请求保留；Router 负责策略、模型准入、Judge 和受管模型费用。</p><h2 id="六种策略" tabindex="-1">六种策略 <a class="header-anchor" href="#六种策略" aria-label="Permalink to &quot;六种策略&quot;">​</a></h2><table tabindex="0"><thead><tr><th>策略</th><th>决策边界</th><th>执行器的变化</th></tr></thead><tbody><tr><td>Static</td><td>新任务选一次</td><td>固定角色，或按权重随机一次并保持</td></tr><tr><td>Stage</td><td>新的可信工具证据</td><td>高效起步、困难时临时接管、保持后可恢复</td></tr><tr><td>Task</td><td>新任务开始</td><td>从自选模型池选择主模型，任务内保持</td></tr><tr><td>Composite</td><td>Task 初选 + 后续 Stage</td><td>常用模型与指定接管模型之间切换</td></tr><tr><td>Advisor Gate</td><td>最终候选边界</td><td>固定执行器，最多一次返工并复审</td></tr><tr><td>Escalation</td><td>起始模型的未交付候选</td><td>一次接管后固定使用接管模型</td></tr></tbody></table><p>具体行为见<a href="./strategies/">策略概览</a>。</p><h2 id="在-dsh-中设置" tabindex="-1">在 DSH 中设置 <a class="header-anchor" href="#在-dsh-中设置" aria-label="Permalink to &quot;在 DSH 中设置&quot;">​</a></h2><p>设置位于独立的 <strong>RefractAgent 规划路由</strong> 卡片，不与自动路由的 DAG 配置混放。</p><ol><li>配置共用模型资料、预算和数据域。</li><li>选择正在编辑的策略，填写该策略真正需要的模型与 Judge。</li><li>核对价格与能力诊断，运行零调用检查。</li><li>保存后，在对话模型菜单的“路由模式”中选择。</li></ol><p>“正在编辑的策略”不等于“默认路由策略”。保存设置从下个任务生效；正在运行的任务使用 已冻结配置。默认策略不应强行覆盖会话已经选择的模式。</p><h2 id="新任务与续接" tabindex="-1">新任务与续接 <a class="header-anchor" href="#新任务与续接" aria-label="Permalink to &quot;新任务与续接&quot;">​</a></h2><p>新用户轮次建立新任务状态。工具续接、进行中的追加指导和宿主压缩沿用当前状态， 不重新取得预算、不重复 Task 分类、不清零审核或升级计数。</p><p>标准模型接口需要可靠关联任务身份与历史。不能把首条消息的 hash 当成通用真实任务 ID； 身份无法确定的接入方式按其支持边界限制，不猜测兼容。</p><h2 id="输出与取消" tabindex="-1">输出与取消 <a class="header-anchor" href="#输出与取消" aria-label="Permalink to &quot;输出与取消&quot;">​</a></h2><p>Static、Stage、Task、Composite 在选模后允许正常流式文本。 Advisor 和 Escalation 的待判别候选需要缓冲；未接受的文本与工具调用不会交付。 已经释放的文本不能被策略悄悄替换。接管后的 Escalation 可以流式输出，并注明未追加审核。</p><p>取消释放未派发的保护额度；已经派发的调用继续结算或保留待核对预留。 模型用量未知、认证／传输故障、账本或证据写入失败时停止后续受管调用。</p><h2 id="配置可执行不等于质量已通过" tabindex="-1">配置可执行不等于质量已通过 <a class="header-anchor" href="#配置可执行不等于质量已通过" aria-label="Permalink to &quot;配置可执行不等于质量已通过&quot;">​</a></h2><p>零调用诊断核对模型、能力、价格、预算、信任和接口要求，不评价实际任务质量。 Judge 是辅助信号，最终仍需要你的验收条件。所有失败尝试、判别和被丢弃回复均需计入费用。</p>',17)])])}const _=a(i,[["render",o]]);export{u as __pageData,_ as default};
